#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct StructStatementIntro<'source> {
    start: usize,
    visibility: Option<VisibilityPrefix<'source>>,
    after_visibility: Option<TriviaRun>,
    struct_keyword: WordSpan<'source>,
    struct_base: usize,
}

