        let records = output.committed_recoveries();
        assert_eq!(records.len(), 2);
        assert_eq!(records[0].kind, RecoveryKind::Missing);
        assert_eq!(
            records[0].site.role,
            GrammarRole::Declaration(DeclarationRole::Struct(crate::session::StructRole::Field)),
        );
